export const updateFallbackAllowed=({online,failed,elapsed})=>!online||!!failed||elapsed>=8000;
// A cached update gates interaction; offline/error/slow activation always has an escape.
export function installUpdateGate({beforeReload,onReady}){
  if(!('serviceWorker' in navigator))return;
  let registration,dialog,worker,applying=false,hadController=!!navigator.serviceWorker.controller,started=0,failed=false,timer,slowTimer;
  const refresh=()=>{if(!dialog)return;const fallback=updateFallbackAllowed({online:navigator.onLine,failed,elapsed:applying?Date.now()-started:0}),button=dialog.querySelector('[data-update-later]');button.hidden=!fallback;button.textContent=!navigator.onLine?'Seguir sin conexión':'Continuar con esta versión';dialog.querySelector('#update-message').textContent=!navigator.onLine?'Estás sin conexión. Podés seguir trabajando y actualizar cuando vuelva.':failed?'No pudimos completar la actualización. Tus datos siguen acá.':applying?'Preparando Mora. Conservamos el borrador antes de cambiar de versión.':'La nueva versión ya está descargada. Actualizá para seguir con Mora.';if(fallback&&applying){dialog.querySelector('[data-update-now]').disabled=false;dialog.querySelector('[data-update-now]').textContent='Reintentar actualización';}};
  const close=()=>{applying=false;if(dialog){dialog.close();dialog.remove();dialog=null;}clearInterval(timer);clearTimeout(slowTimer);};
  const apply=()=>{try{beforeReload();}catch{failed=true;refresh();return;}applying=true;failed=false;started=Date.now();dialog.querySelector('[data-update-now]').disabled=true;dialog.querySelector('[data-update-now]').textContent='Actualizando…';refresh();slowTimer=setTimeout(refresh,8100);if(worker)worker.postMessage({type:'ACTIVATE'});else window.location.reload();};
  const show=w=>{worker=w;if(dialog){refresh();return;}failed=false;applying=false;dialog=document.createElement('dialog');dialog.className='mora-update-dialog';dialog.setAttribute('aria-labelledby','update-title');dialog.setAttribute('aria-describedby','update-message');dialog.innerHTML='<div class="update-brand">MORA<i></i></div><span class="eyebrow">Una nueva versión</span><h2 id="update-title" tabindex="-1" autofocus>Mora está lista<br>para actualizarse.</h2><p id="update-message"></p><button class="btn primary" data-update-now>Actualizar Mora</button><button class="text-btn" data-update-later hidden></button><small>Los datos se conservan en este navegador.</small>';
    document.body.append(dialog);dialog.addEventListener('cancel',e=>{e.preventDefault();if(updateFallbackAllowed({online:navigator.onLine,failed,elapsed:applying?Date.now()-started:0}))close();});dialog.querySelector('[data-update-now]').addEventListener('click',apply);dialog.querySelector('[data-update-later]').addEventListener('click',close);dialog.showModal();dialog.querySelector('#update-title').focus({preventScroll:true});refresh();timer=setInterval(refresh,1000);
    // Probe actual origin reachability without asking a slow connection to hold the app hostage.
    fetch('./index.html',{cache:'no-store',signal:AbortSignal.timeout(8000)}).then(r=>{if(!r.ok){failed=true;refresh();}}).catch(()=>{failed=true;refresh();});
  };
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(applying){window.location.reload();return;}if(hadController)show(null);hadController=true;});
  const check=()=>registration?.update().catch(()=>{});window.addEventListener('online',()=>{refresh();check();});window.addEventListener('offline',refresh);window.addEventListener('focus',check);setInterval(()=>{if(document.visibilityState==='visible')check();},60000);
  navigator.serviceWorker.register('./sw.js').then(reg=>{registration=reg;const watch=()=>{if(reg.waiting&&hadController)show(reg.waiting);};watch();reg.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',watch));return navigator.serviceWorker.ready;}).then(()=>onReady()).catch(()=>{});
}
